                                    className="block overflow-hidden border border-slate-200 bg-slate-50 rounded-lg shadow-sm"
                                    disabled={!fileUrl}
                                >
                                    {fileUrl ? (
                                        <img 
                                            src={fileUrl} 
                                            alt={message.filePreview.name} 
                                            onLoad={onImageLoad}
                                            className="max-w-[150px] md:max-w-[200px] max-h-[150px] md:max-h-[200px] object-contain block group-hover/img:scale-105 transition-transform duration-500" 
                                        />
                                    ) : (
                                        <div className="w-[150px] h-[150px] flex items-center justify-center bg-slate-100 animate-pulse text-slate-400 text-xs">
                                            Loading from Vault...
                                        </div>
                                    )}
                                </button>
                                <div className="mt-2 flex items-center justify-between text-[10px] font-mono text-slate-400 max-w-[200px]">
                                    <span className="truncate">{message.filePreview.name}</span>
                                    <span className="text-blue-600 opacity-0 group-hover/img:opacity-100 transition-opacity cursor-pointer font-bold tracking-wider">[EXPAND]</span>
                                </div>
                            </div>
                        ) : (
                             <div className="flex items-center gap-3 p-3 bg-slate-50 border border-slate-200 rounded-xl w-fit pr-6 shadow-sm">
                                <div className="p-2 bg-white rounded-lg border border-slate-100 shadow-sm">
                                    <DocumentTextIcon className="w-5 h-5 text-blue-500" />
                                </div>
                                <div>
                                    <p className="font-medium text-xs text-slate-700">{message.filePreview.name}</p>
                                    <p className="text-[10px] text-slate-400 uppercase tracking-wide mt-0.5">Ready for Analysis</p>
                                 </div>
                            </div>
                        )}
                    </div>
                )}

                <MessageContent 
                    content={contentToRender} 
                    role={message.role} 
                    isLoading={!!isLoading} 
                    isLast={!!isLast} 
                />

                {message.sources && message.sources.length > 0 && (
                    <div className="mt-6 pt-4 border-t border-slate-100">
                        <div className="flex items-center gap-2 mb-3">
                            <ShieldCheckIcon className="w-3 h-3 text-slate-400" />
                            <span className="text-[10px] font-mono font-bold text-slate-400 uppercase tracking-widest">Verified Sources</span>
                        </div>
                        <div className="flex flex-wrap gap-2">
                            {message.sources.map((source, i) => {
                                if (source.web) {
                                    const isTrusted = isHighCredibilitySource(source.web.uri);
                                    return (
                                        <a key={i} href={source.web.uri} target="_blank" rel="noopener noreferrer"
                                            className={`flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold border transition-all rounded-full max-w-full
                                                ${isTrusted 
                                                    ? 'bg-emerald-50 border-emerald-100 text-emerald-600 hover:bg-emerald-100' 
                                                    : 'bg-slate-50 border-slate-200 text-slate-500 hover:bg-slate-100'
                                                }`}
                                        >
                                            {isTrusted ? <ShieldCheckIcon className="w-3 h-3 text-emerald-500" /> : <LinkIcon className="w-3 h-3 text-slate-400" />}
                                            <span className="truncate max-w-[200px]">{source.web.title}</span>
                                        </a>
                                    );
                                }
                                if (source.maps) {
                                    return (
                                        <a key={i} href={source.maps.uri} target="_blank" rel="noopener noreferrer"
                                            className="flex items-center gap-1.5 bg-blue-50 hover:bg-blue-100 border border-blue-100 px-3 py-1.5 text-[10px] font-bold text-blue-600 transition-all rounded-full"
                                        >
                                            <MapPinIcon className="w-3 h-3 text-blue-500" />
                                            <span className="truncate max-w-[200px]">{source.maps.title}</span>
                                        </a>
                                    );
                                }
                                return null;
                            })}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default Message;

import React, { useRef, useCallback } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { ChatMode as ChatModeEnum, UploadedFile, ChatMessage, GroundingSource } from '../../../types';
import { generateResponseStream } from '../../../services/geminiService';
import { exportBriefingToPdf } from '../../../services/exportService';
import { cleanJsonOutput, isJsonBriefing, getFriendlyErrorMessage, isLabReport, parseJsonSafe } from '../../../utils';
import { FILE_ANALYSIS_PROMPT, BRIEFING_TRIGGERS, SHIFT_BRIEFING_PROMPT, HELP_COMMAND_RESPONSE, DRUG_ANALYSIS_PROMPT } from '../../../constants';
import { usePatientStore } from '../../patient-management/usePatientStore';
import { useChatStore } from '../stores/useChatStore';
import { useClinicalStore } from '../../clinical-analysis/stores/useClinicalStore';
import { useEntityExtractor } from '../../../hooks/useEntityExtractor';
import { FHIRObservation } from '../../fhir/types';
import { evaluateClinicalSafety } from '../../cdss/rulesEngine';
import { PatientMetadata } from '../../patient-management/types';
import { UIAction } from '../../ui/UIContext';

interface UseChatOrchestratorProps {
    messages: ChatMessage[];
    activePatientId: string;
    activePatient: PatientMetadata;
    chatMode: ChatModeEnum;
    uiDispatch: React.Dispatch<UIAction>;
    uploadedFile: UploadedFile | null;
    setUploadedFile: (file: UploadedFile | null) => void;
    isLive: boolean;
    stopSession: () => void;
    userLocation?: { latitude: number, longitude: number };
    clearFile: () => void;
}

export const useChatOrchestrator = ({
    messages,
    activePatientId,
    activePatient,
    chatMode,
    uiDispatch,
    uploadedFile,
    setUploadedFile,
    isLive,
    stopSession,
    userLocation,
    clearFile
}: UseChatOrchestratorProps) => {
    // Access actions from all 3 stores
    const patientActions = usePatientStore(state => state.actions);
    const chatActions = useChatStore(state => state.actions);
    const clinicalActions = useClinicalStore(state => state.actions);

    const abortControllerRef = useRef<AbortController | null>(null);
    const { triggerExtraction } = useEntityExtractor();

    const handleStop = useCallback(() => {
        if (abortControllerRef.current) abortControllerRef.current.abort();
        uiDispatch({ type: 'SET_LOADING', payload: false });
    }, [uiDispatch]);

    const handleClearChat = useCallback(() => {
        chatActions.resetChat(activePatientId);
        clearFile();
    }, [chatActions, activePatientId, clearFile]);

    const handleSend = useCallback(async (userPrompt: string) => {
        const trimmedPrompt = userPrompt.trim();
        if (!trimmedPrompt && !uploadedFile) return;

        if (isLive) {
            stopSession();
            uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Standard });
        }

        // Update last active
        patientActions.touchPatient(activePatientId);

        // --- Export Command ---
        if (trimmedPrompt.toLowerCase() === '/export') {
            const history = messages.filter(m => !isJsonBriefing(m.content));
            if (history.length === 0) {
                 chatActions.addMessage(activePatientId, { role: 'model', content: '⚠️ **Cannot Export:** No history available.' });
                 return;
            }

            chatActions.addMessage(activePatientId, { role: 'model', content: '📥 Generating briefing for PDF export...' });
            uiDispatch({ type: 'SET_LOADING', payload: true });

            abortControllerRef.current = new AbortController();
            try {
                const modeForRequest = ChatModeEnum.Standard;
                // Note: History messages in store do not have base64 now. 
                // geminiService handles fetching text. For images in export, it might be tricky, 
                // but PDF export usually just needs text structure.
                const stream = generateResponseStream(SHIFT_BRIEFING_PROMPT(), history, modeForRequest, { responseType: 'json' });
                let fullResponseText = '';
                for await (const chunk of stream) {
                    if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");
                    fullResponseText += chunk.text;
                }

                if (fullResponseText.includes("NO DATA")) throw new Error("Insufficient clinical data found.");

                const cleanedJson = cleanJsonOutput(fullResponseText);
                if (!cleanedJson.startsWith('{')) throw new Error("Invalid briefing format.");

                const parsedBriefing = JSON.parse(cleanedJson);
                if (parsedBriefing.briefingTitle && parsedBriefing.briefingTitle.includes("NO DATA")) throw new Error("Insufficient clinical data.");

                await exportBriefingToPdf(parsedBriefing);
                chatActions.updateLastMessageContent(activePatientId, '✅ Shift briefing PDF downloaded.');
            } catch (e) {
                if (e.message === "Aborted") {
                     chatActions.updateLastMessageContent(activePatientId, '🛑 Export cancelled.');
                } else {
                    const friendlyError = getFriendlyErrorMessage(e);
                    chatActions.updateLastMessageContent(activePatientId, `Sorry, PDF generation failed.\n\n**Reason:** ${friendlyError}`);
                }
            } finally {
                uiDispatch({ type: 'SET_LOADING', payload: false });
                abortControllerRef.current = null;
            }
            return;
        }

        // --- Help Command ---
        if (trimmedPrompt.toLowerCase() === '/help') {
             chatActions.addMessage(activePatientId, { role: 'user', content: '/help' });
             chatActions.addMessage(activePatientId, { role: 'model', content: HELP_COMMAND_RESPONSE });
             return;
        }

        // --- Standard Message & File Handling ---
        let finalApiPrompt = trimmedPrompt;
        let historyContent = trimmedPrompt;

        // This object is for the API call (needs base64)
        let fileForApi: UploadedFile | undefined = uploadedFile || undefined;

        let displayOverride = undefined;
        let modeForRequest: ChatModeEnum = chatMode === ChatModeEnum.Live ? ChatModeEnum.Standard : chatMode;
        let responseType: 'json' | 'text' = 'text';

        const isBriefingCommand = BRIEFING_TRIGGERS.some(trigger => trimmedPrompt.toLowerCase().includes(trigger)) || trimmedPrompt.toLowerCase() === '/brief';
        const isDrugCommand = trimmedPrompt.toLowerCase().startsWith('/drugs');

        if (uploadedFile) {
             // TRIGGER BACKGROUND EXTRACTION
             if (activePatientId) {
                 triggerExtraction(uploadedFile, activePatientId);
             }

             try {
                let analysisPrompt: string;
                if (uploadedFile.type === 'application/pdf') {
                    const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this medical document.`;
                    analysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name) + `\n\n${promptBase}`;
                } else if (uploadedFile.type === 'text/plain' || uploadedFile.file.name.endsWith('.txt') || uploadedFile.file.name.endsWith('.md')) {
                     // Text files are embedded directly, no need for blob handling in message
                     // We read the file here since it's already in memory from the input
                     // NOTE: uploadedFile.file is the File object.
                     const textContent = await uploadedFile.file.text();
                     const promptBase = trimmedPrompt ? `User Query: ${trimmedPrompt}` : `Analyze this document.`;
                     const fullEmbeddedContent = `*** BEGIN FILE CONTENT: ${uploadedFile.file.name} ***\n${textContent}\n*** END FILE CONTENT ***\n\n${promptBase}`;
                     analysisPrompt = fullEmbeddedContent;
                     historyContent = fullEmbeddedContent;
                     displayOverride = `📄 **Uploaded ${uploadedFile.file.name}**\n\n${trimmedPrompt || "Requested analysis."}`;
                     fileForApi = undefined; // Don't send as inlineData
                } else {
                    // Images
                    const baseAnalysisPrompt = FILE_ANALYSIS_PROMPT(uploadedFile.file.name);
                    if (!trimmedPrompt) {
                        analysisPrompt = baseAnalysisPrompt;
                        displayOverride = `Analyzing file: ${uploadedFile.file.name}`; 
                    } else {
                        analysisPrompt = `${baseAnalysisPrompt}\n\n---\n**ADDITIONAL INSTRUCTION:**\nThe user has asked: "${trimmedPrompt}".\n1. You MUST still output VALID JSON.\n2. Answer the user's question within the "visualObservations" or "note" fields.`;
                    }
                }

                finalApiPrompt = analysisPrompt;
                if (isBriefingCommand) {
                    finalApiPrompt = `${finalApiPrompt}\n\nIMPORTANT: After analyzing, ${SHIFT_BRIEFING_PROMPT()}`;
                    modeForRequest = ChatModeEnum.Standard;
                    responseType = 'json';
                    if (!displayOverride) historyContent = trimmedPrompt || "/brief (with file)";
                }
             } catch (error) {
                 chatActions.addMessage(activePatientId, { role: 'model', content: `Error: ${getFriendlyErrorMessage(error)}` });
                 uiDispatch({ type: 'SET_ERROR', payload: getFriendlyErrorMessage(error) });
                 return;
             }
        } else if (isBriefingCommand) {
            finalApiPrompt = SHIFT_BRIEFING_PROMPT();
            historyContent = "/brief"; 
            modeForRequest = ChatModeEnum.Standard;
            responseType = 'json';
        } else if (isDrugCommand) {
            finalApiPrompt = DRUG_ANALYSIS_PROMPT(trimmedPrompt);
            modeForRequest = ChatModeEnum.Standard; 
            responseType = 'json';
        }

        if (trimmedPrompt.toLowerCase().startsWith('/patient')) modeForRequest = ChatModeEnum.Standard;

        // UI Updates - Store Message (NO BASE64 HERE)
        const userMessage: ChatMessage = { role: 'user', content: historyContent };
        if (displayOverride) userMessage.displayContent = displayOverride;

        if (uploadedFile && fileForApi) { // Only add filePreview if we are actually treating it as an image/blob
            userMessage.filePreview = { 
                name: uploadedFile.file.name, 
                type: uploadedFile.type, 
                url: uploadedFile.url, // Keep ephemeral URL for immediate display
                storageId: uploadedFile.storageId // Persist ID
            };
        }

        chatActions.addMessage(activePatientId, userMessage);
        chatActions.addResponsePlaceholder(activePatientId);
        uiDispatch({ type: 'SET_LOADING', payload: true });
        uiDispatch({ type: 'SET_ERROR', payload: null });
        setUploadedFile(null);

        // API Call
        abortControllerRef.current = new AbortController();
        let fullResponseBuffer = '';

        try {
            const history = [...messages];
            // Pass fileForApi which contains base64 for the active request.
            // geminiService will use this active file for the request.
            const stream = generateResponseStream(finalApiPrompt, history, modeForRequest, { file: fileForApi, responseType, location: userLocation });

            for await (const chunk of stream) {
                if (abortControllerRef.current?.signal.aborted) throw new Error("Aborted");

                const textChunk = chunk.text || '';
                fullResponseBuffer += textChunk;

                const groundingMetadata = chunk.candidates?.[0]?.groundingMetadata;
                let sources: GroundingSource[] | undefined = undefined;

                if (groundingMetadata && groundingMetadata.groundingChunks) {
                    sources = groundingMetadata.groundingChunks.map(chunk => {
                        if (chunk.web) return { web: chunk.web };
                        if ((chunk as any).maps) return { maps: (chunk as any).maps };
                        return undefined;
                    }).filter(Boolean) as GroundingSource[];
                }

                chatActions.appendToLastMessage(activePatientId, textChunk, sources);
            }
        } catch (e) {
             if (e.message === "Aborted") {
                 chatActions.appendToLastMessage(activePatientId, " [Stopped]", undefined);
            } else {
                const errorMsg = `Sorry, I encountered an error.\n\n**Details:** ${getFriendlyErrorMessage(e)}`;
                chatActions.updateLastMessageContent(activePatientId, errorMsg);
            }
        } finally {
            uiDispatch({ type: 'SET_LOADING', payload: false });

            // --- FHIR AUTO-INGESTION PROTOCOL ---
            if (activePatientId && isLabReport(fullResponseBuffer)) {
                const report = parseJsonSafe<any>(fullResponseBuffer);
                if (report && report.labs) {
                    const newObs: FHIRObservation[] = report.labs.map((lab: any) => {
                         const val = parseFloat(lab.value.replace(/[^0-9.-]/g, ''));
                         const rangeMatch = lab.refRange.match(/([\d.]+)\s*-\s*([\d.]+)/);

                         if (isNaN(val)) return null;

                         const obs: FHIRObservation = {
                             resourceType: 'Observation',
                             id: uuidv4(),
                             status: 'final',
                             code: { 
                                 text: lab.testName 
                             },
                             subject: { reference: `Patient/${activePatientId}` },
                             valueQuantity: { 
                                 value: val, 
                                 unit: lab.units,
                                 system: 'http://unitsofmeasure.org'
                             },
                             effectiveDateTime: report.date && report.date !== 'Not Visible' ? new Date(report.date).toISOString() : new Date().toISOString(),
                             issued: new Date().toISOString()
                         };

                         if (rangeMatch) {
                             obs.referenceRange = [{
                                 low: { value: parseFloat(rangeMatch[1]), unit: lab.units, system: 'http://unitsofmeasure.org' },
                                 high: { value: parseFloat(rangeMatch[2]), unit: lab.units, system: 'http://unitsofmeasure.org' },
                                 text: lab.refRange
                             }];
                         }

                         if (lab.flag && lab.flag !== 'Normal') {
                             obs.interpretation = [{ text: lab.flag }];
                         }

                         return obs;
                    }).filter(Boolean);

                    if (newObs.length > 0) {
                        clinicalActions.ingestObservations(activePatientId, newObs);

                        const existingObs = useClinicalStore.getState().data[activePatientId]?.observations || [];
                        const combinedObs = [...existingObs, ...newObs];

                        evaluateClinicalSafety(combinedObs).then(alerts => {
                            if (alerts.length > 0) {
                                clinicalActions.updateAlerts(activePatientId, alerts);
                            }
                        });
                    }
                }
            }

            abortControllerRef.current = null;
        }
    }, [messages, activePatientId, chatMode, uploadedFile, isLive, stopSession, userLocation, patientActions, chatActions, clinicalActions, uiDispatch, setUploadedFile, triggerExtraction]);

    return {
        handleSend,
        handleStop,
        handleClearChat,
        handleExportChat: useCallback(() => handleSend('/export'), [handleSend])
    };
};

import { GoogleGenAI, GenerateContentResponse, Content, Part, GenerateContentParameters } from "@google/genai";
import type { ChatMessage, ChatMode, UploadedFile } from '../types';
import { MODEL_CONFIGS, SYSTEM_INSTRUCTION } from '../constants';

// Helper to convert our app's message format to Gemini's format.
const messageToContent = (message: ChatMessage, isHistory: boolean = false): Content => {
    const parts: Part[] = [];

    // If the message has a persistent file attached
    if (message.filePreview) {
        // COST OPTIMIZATION & STORAGE SAFETY:
        // We strictly control when to send base64 image data.
        // 1. We NEVER send base64 if isHistory is true (saves tokens).
        // 2. We check if the message object even HAS base64 (it shouldn't if loaded from store).

        // Note: The 'UploadedFile' object passed in 'options' to generateResponseStream
        // contains the base64 for the *current* turn. ChatMessage history does not.

        // "Zombie" / Context Preservation Logic:
        // If data is missing (reload) OR if we intentionally stripped it (history optimization),
        // we inject a System Note. This prevents the model from hallucinating that it "can't see" anything,
        // by explicitly telling it to rely on memory/previous analysis.

        const isImage = message.filePreview.type.startsWith('image/');

        if (isImage) {
             parts.push({ 
                text: `[System Note: The user attached an image named "${message.filePreview.name}" in a previous turn. To conserve tokens, the image data is not re-sent. Please rely on your previous analysis of this image.]` 
            });
        } 
    }

    if (message.content) {
        let textToSend = message.content;
        parts.push({ text: textToSend });
    }

    return { role: message.role, parts };
};

const consolidateContents = (contents: Content[]): Content[] => {
    if (contents.length === 0) return [];

    const consolidated: Content[] = [];
    let currentRole = contents[0].role;
    let currentParts: Part[] = [...contents[0].parts];

    for (let i = 1; i < contents.length; i++) {
        const msg = contents[i];
        if (msg.role === currentRole) {
            currentParts = [...currentParts, ...msg.parts];
        } else {
            consolidated.push({ role: currentRole, parts: currentParts });
            currentRole = msg.role;
            currentParts = [...msg.parts];
        }
    }
    consolidated.push({ role: currentRole, parts: currentParts });

    return consolidated;
};

interface GenerateResponseOptions {
  file?: UploadedFile;
  responseType?: 'json' | 'text';
  location?: { latitude: number; longitude: number };
}

export const generateResponseStream = async function* (
  prompt: string,
  history: ChatMessage[],
  mode: ChatMode,
  options?: GenerateResponseOptions
): AsyncGenerator<GenerateContentResponse> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const modelConfig = MODEL_CONFIGS[mode];
  const file = options?.file;

  // 1. Filter out completely empty messages (safety check)
  const rawHistory = history.filter(msg => {
     return (msg.content && msg.content.trim() !== '') || (msg.filePreview !== undefined);
  });

  // 2. INTELLIGENT CONTEXT PRUNING ("Adaptive Budget")
  // Different models have different cost/latency profiles.
  // We dynamically adjust the window size based on the active mode.

  const MAX_TEXT_TURNS = (modelConfig as any).contextLimit || 15;

  const medicalRecords = rawHistory.filter(msg => msg.filePreview !== undefined);
  const conversation = rawHistory.filter(msg => msg.filePreview === undefined);
  const recentConversation = conversation.slice(-MAX_TEXT_TURNS);
  const keptMessagesSet = new Set([...medicalRecords, ...recentConversation]);
  const historyToProcess = rawHistory.filter(msg => keptMessagesSet.has(msg));

  // Map history to API Content objects.
  // Pass 'true' to isHistory to strip expensive image binaries / force placeholder usage.
  let contents: Content[] = historyToProcess.map(msg => messageToContent(msg, true));
  contents = consolidateContents(contents);

  const currentMessageParts: Part[] = [];

  // This is the ONLY place where actual image binary data is sent to the model
  // It comes from the 'file' option (current upload), NOT the chat history state.
  if (file && file.base64) {
    currentMessageParts.push({
      inlineData: {
        mimeType: file.type,
        data: file.base64,
      },
    });
  }

  currentMessageParts.push({ text: prompt });

  contents.push({ role: 'user', parts: currentMessageParts });

  const responseStream = await ai.models.generateContentStream({
    model: modelConfig.model,
    contents: contents,
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      ...modelConfig.config,
      ...(options?.responseType === 'json' ? { responseMimeType: 'application/json' } : {}),
      ...(options?.location ? {
         toolConfig: {
             retrievalConfig: {
                 latLng: {
                     latitude: options.location.latitude,
                     longitude: options.location.longitude
                 }
             }
         } as any
      } : {})
    },
  });

  for await (const chunk of responseStream) {
    yield chunk;
  }
};

import React from 'react';
import { CDSSAlert } from './types';
import { AlertTriangleIcon, CheckIcon, ShieldCheckIcon, BoltIcon } from '../../components/icons';

interface InterventionCardProps {
    alert: CDSSAlert;
    onAction: (alert: CDSSAlert, actionIndex: number) => void;
    variant?: 'toast' | 'banner';
}

const InterventionCard: React.FC<InterventionCardProps> = ({ alert, onAction, variant = 'toast' }) => {
    const isCritical = alert.level === 'Critical';
    const isBanner = variant === 'banner';

    // --- CRITICAL BANNER (MODAL OVERLAY STYLE) ---
    if (isBanner) {
        return (
            <div className="w-full bg-red-600 text-white rounded-lg shadow-[0_0_40px_rgba(220,38,38,0.4)] border-2 border-red-400 overflow-hidden animate-slide-up relative">
                {/* Background Texture */}
                <div className="absolute inset-0 opacity-10 bg-[repeating-linear-gradient(45deg,transparent,transparent_10px,#000_10px,#000_20px)] pointer-events-none"></div>

                <div className="relative z-10 p-5 md:p-6 flex flex-col md:flex-row items-start md:items-center gap-5 md:gap-6">
                    {/* Icon Block */}
                    <div className="flex-shrink-0">
                        <div className="p-4 bg-white/20 rounded-full animate-pulse shadow-inner">
                            <AlertTriangleIcon className="w-8 h-8 text-white" />
                        </div>
                    </div>

                    {/* Content Block */}
                    <div className="flex-1 min-w-0">
                        <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mb-2">
                            <h3 className="text-xl font-display font-bold uppercase tracking-widest text-white leading-none">
                                {alert.title}
                            </h3>
                            <span className="bg-red-950/40 px-2 py-0.5 rounded text-[10px] font-mono uppercase tracking-widest border border-red-400/50 text-red-100">
                                Immediate Action Required
                            </span>
                        </div>
                        <p className="text-red-50 text-sm font-medium leading-relaxed max-w-2xl mb-3">
                            {alert.description}
                        </p>
                        <div className="flex flex-wrap gap-2">
                             {alert.triggers.map((t, i) => (
                                <span key={i} className="text-[10px] font-mono bg-black/20 px-2 py-1 rounded text-red-100 border border-white/10 flex items-center gap-1.5">
                                    <span className="w-1.5 h-1.5 bg-red-400 rounded-full animate-pulse"></span>
                                    {t}
                                </span>
                            ))}
                        </div>
                    </div>

                    {/* Actions Block */}
                    <div className="flex flex-col gap-2 w-full md:w-auto min-w-[180px] flex-shrink-0">
                        {alert.actions.map((action, idx) => (
                            <button
                                key={idx}
                                onClick={() => onAction(alert, idx)}
                                className={`
                                    w-full py-3 px-4 text-xs font-bold uppercase tracking-widest rounded shadow-lg transition-transform active:scale-95 flex items-center justify-center gap-2
                                    ${action.type === 'dismiss' 
                                        ? 'bg-red-800 hover:bg-red-900 text-red-200 border border-red-700' 
                                        : 'bg-white text-red-700 hover:bg-red-50 border-b-4 border-red-200'
                                    }
                                `}
                            >
                                {action.type === 'order' && <BoltIcon className="w-4 h-4" />}
                                {action.type === 'acknowledge' && <CheckIcon className="w-4 h-4" />}
                                {action.type === 'dismiss' && <span>Ignore</span>}
                                <span>{action.label}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    // --- STANDARD TOAST (NON-INTRUSIVE) ---
    return (
        <div className={`
            w-full max-w-sm rounded-sm shadow-xl border-l-4 animate-slide-up mb-3 overflow-hidden backdrop-blur-md transition-all hover:scale-[1.02]
            ${isCritical 
                ? 'bg-red-50/95 dark:bg-slate-900/95 border-red-500 border-y border-r border-slate-200 dark:border-slate-800' 
                : 'bg-amber-50/95 dark:bg-slate-900/95 border-amber-500 border-y border-r border-slate-200 dark:border-slate-800'}
        `}>
            {/* Header */}
            <div className={`px-4 py-2 flex items-center justify-between ${isCritical ? 'bg-red-100/50 dark:bg-red-900/20' : 'bg-amber-100/50 dark:bg-amber-900/20'}`}>
                <div className="flex items-center gap-2">
                    <AlertTriangleIcon className={`w-4 h-4 ${isCritical ? 'text-red-600' : 'text-amber-600'}`} />
                    <span className={`text-xs font-mono font-bold uppercase tracking-widest ${isCritical ? 'text-red-700 dark:text-red-400' : 'text-amber-700 dark:text-amber-400'}`}>
                        {alert.title}
                    </span>
                </div>
                <div className="flex gap-1">
                    {alert.triggers.slice(0, 2).map((t, i) => (
                        <span key={i} className="text-[9px] font-mono bg-white/50 dark:bg-black/50 px-1.5 py-0.5 rounded-sm border border-black/5 dark:border-white/10">
                            {t}
                        </span>
                    ))}
                </div>
            </div>

            {/* Content */}
            <div className="p-4">
                <p className="text-sm text-slate-700 dark:text-slate-300 leading-relaxed mb-4">
                    {alert.description}
                </p>

                {/* Actions */}
                <div className="flex flex-wrap gap-2">
                    {alert.actions.map((action, idx) => {
                        const isDismiss = action.type === 'dismiss';
                        return (
                            <button
                                key={idx}
                                onClick={() => onAction(alert, idx)}
                                className={`
                                    flex items-center gap-1.5 px-3 py-1.5 text-xs font-bold uppercase tracking-wide rounded-sm transition-all
                                    ${isDismiss 
                                        ? 'bg-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 border border-transparent hover:border-slate-300' 
                                        : isCritical 
                                            ? 'bg-red-600 hover:bg-red-500 text-white shadow-sm' 
                                            : 'bg-amber-500 hover:bg-amber-400 text-white shadow-sm'
                                    }
                                `}
                            >
                                {action.type === 'order' && <BoltIcon className="w-3 h-3" />}
                                {action.type === 'acknowledge' && <CheckIcon className="w-3 h-3" />}
                                {action.type === 'dismiss' && <span className="text-lg leading-none">×</span>}
                                <span>{action.label}</span>
                            </button>
                        );
                    })}
                </div>
            </div>
        </div>
    );
};

export default InterventionCard;

import React from 'react';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useClinicalStore } from '../clinical-analysis/stores/useClinicalStore';
import { useChatStore } from '../chat/stores/useChatStore';
import InterventionCard from './InterventionCard';
import { CDSSAlert } from './types';

const CDSSContainer: React.FC = () => {
    const activePatientId = usePatientStore(state => state.activePatientId);

    // Select Alerts from Clinical Store
    const activeAlerts = useClinicalStore(state => state.alerts[activePatientId] || []);
    const clinicalActions = useClinicalStore(state => state.actions);
    const chatActions = useChatStore(state => state.actions);

    if (activeAlerts.length === 0) return null;

    const handleAction = (alert: CDSSAlert, actionIndex: number) => {
        const action = alert.actions[actionIndex];

        if (action.type === 'dismiss') {
            clinicalActions.dismissAlert(activePatientId, alert.ruleId);
        } else if (action.type === 'order' || action.type === 'acknowledge') {
            // Inject the action into the chat as a system note or user action
            if (action.payload) {
                chatActions.addMessage(activePatientId, { 
                    role: 'model', 
                    content: `✅ **ACTION EXECUTED**: ${action.payload}\n\n*Protocol: ${alert.title}*` 
                });
            }
            clinicalActions.dismissAlert(activePatientId, alert.ruleId);
        }
    };

    // Filter alerts into visibility tiers
    const criticalAlerts = activeAlerts.filter(a => a.level === 'Critical');
    const standardAlerts = activeAlerts.filter(a => a.level !== 'Critical');

    return (
        <>
            {/* TIER 1: CRITICAL INTERVENTION LAYER (BLOCKING OVERLAY) */}
            {/* Sits on top of everything except the absolute header, dims the chat content */}
            {criticalAlerts.length > 0 && (
                <div className="fixed inset-0 z-[60] flex items-start justify-center pt-20 md:pt-32 bg-slate-900/40 backdrop-blur-[3px] pointer-events-auto px-4 pb-4 overflow-y-auto animate-fade-in">
                    <div className="w-full max-w-3xl flex flex-col gap-4">
                        {criticalAlerts.map(alert => (
                            <InterventionCard 
                                key={alert.id} 
                                alert={alert} 
                                onAction={handleAction} 
                                variant="banner"
                            />
                        ))}
                    </div>
                </div>
            )}

            {/* TIER 2: STANDARD NOTIFICATION LAYER (BOTTOM RIGHT TOASTS) */}
            {/* Non-intrusive updates for warnings and info */}
            {standardAlerts.length > 0 && (
                <div className="absolute bottom-4 right-4 z-40 flex flex-col items-end pointer-events-none">
                    <div className="pointer-events-auto flex flex-col items-end w-full max-w-sm gap-2">
                        {standardAlerts.map(alert => (
                            <InterventionCard 
                                key={alert.id} 
                                alert={alert} 
                                onAction={handleAction}
                                variant="toast" 
                            />
                        ))}
                    </div>
                </div>
            )}
        </>
    );
};

export default CDSSContainer;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import { ChatMode as ChatModeEnum } from '../../types';
import Header from '../../components/Header';
import MessageList from '../chat/components/MessageList';
import InputBar from '../chat/components/InputBar';
import ImageViewer from '../../components/ImageViewer';
import SidebarRoster from '../patient-roster/SidebarRoster';
import HeadsUpDisplay from '../hud/HeadsUpDisplay';
import ScribeInterface from '../scribe/ScribeInterface';
import CDSSContainer from '../cdss/CDSSContainer';
import BioMetricBackground from './BioMetricBackground';
import { useLiveSession } from '../../hooks/useLiveSession';
import { useFileDragAndDrop } from '../../hooks/useFileDragAndDrop';
import { useChatOrchestrator } from '../chat/hooks/useChatOrchestrator';
import { DocumentTextIcon, ShieldCheckIcon, EyeIcon } from '../../components/icons';
import { usePatientStore } from '../patient-management/usePatientStore';
import { useChatStore } from '../chat/stores/useChatStore';
import { useUIStore } from '../ui/UIContext';

// --- IDLE TIMER CONSTANTS ---
const PRIVACY_BLUR_MS = 2 * 60 * 1000; // 2 Minutes -> Blur
const AUTO_LOCK_MS = 15 * 60 * 1000;   // 15 Minutes -> Full Lock

const MainLayout: React.FC = () => {
    // --- STORES ---
    const activePatientId = usePatientStore(state => state.activePatientId);
    const activePatient = usePatientStore(state => state.patients[activePatientId]);
    const chatActions = useChatStore(state => state.actions);

    // Select messages from the specialized Chat Store
    // This is the key optimization: changing clinical data won't re-render MessageList parent
    const activeMessages = useChatStore(state => state.chats[activePatientId] || []);

    const { uiState, uiDispatch } = useUIStore();

    // --- UI State ---
    const { uploadedFile, setUploadedFile, isDragging, clearFile, dragHandlers } = useFileDragAndDrop();
    const { chatMode, isLoading } = uiState;

    // --- Local UI State ---
    const [userLocation, setUserLocation] = useState<{latitude: number, longitude: number} | undefined>(undefined);
    const [viewingImage, setViewingImage] = useState<{src: string, alt: string} | null>(null);
    const [isSidebarOpen, setIsSidebarOpen] = useState(true);

    // Security State
    const [isLocked, setIsLocked] = useState(false);
    const [isBlurred, setIsBlurred] = useState(false);
    const lastActivityRef = useRef(Date.now());

    // --- IDLE LOCK LOGIC ---
    useEffect(() => {
        const resetTimer = () => {
            lastActivityRef.current = Date.now();
            setIsBlurred(prev => prev ? false : prev); // Optimistic unblur
        };

        const checkIdle = () => {
            const idleTime = Date.now() - lastActivityRef.current;

            if (idleTime > AUTO_LOCK_MS) {
                setIsLocked(true);
            } else if (idleTime > PRIVACY_BLUR_MS) {
                setIsBlurred(true);
            }
        };

        // Events to track activity
        window.addEventListener('mousemove', resetTimer);
        window.addEventListener('keydown', resetTimer);
        window.addEventListener('touchstart', resetTimer);
        window.addEventListener('scroll', resetTimer);

        // Check interval
        const intervalId = setInterval(checkIdle, 5000); // Check every 5s

        return () => {
            window.removeEventListener('mousemove', resetTimer);
            window.removeEventListener('keydown', resetTimer);
            window.removeEventListener('touchstart', resetTimer);
            window.removeEventListener('scroll', resetTimer);
            clearInterval(intervalId);
        };
    }, []);

    // Responsive Sidebar Check
    useEffect(() => {
        const handleResize = () => {
            if (window.innerWidth < 768) setIsSidebarOpen(false);
            else setIsSidebarOpen(true);
        };
        handleResize(); // Init
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // --- Geolocation ---
    useEffect(() => {
        if (navigator.geolocation) {
            navigator.geolocation.getCurrentPosition(
                (position) => setUserLocation({ latitude: position.coords.latitude, longitude: position.coords.longitude }),
                (err) => console.debug("Location access denied or failed:", err.message)
            );
        }
    }, []);

    // --- Live Session Integration ---
    const handleLiveTurnComplete = useCallback((userInput: string, modelOutput: string) => {
        if (userInput) chatActions.addMessage(activePatientId, { role: 'user', content: userInput });
        if (modelOutput) chatActions.addMessage(activePatientId, { role: 'model', content: modelOutput });
    }, [chatActions, activePatientId]);

    const { isLive, transcript, startSession, stopSession, error: liveError } = useLiveSession(handleLiveTurnComplete);

    useEffect(() => {
        if (liveError) {
            chatActions.addMessage(activePatientId, { role: 'model', content: `Error: ${liveError}` });
            uiDispatch({ type: 'SET_ERROR', payload: liveError });
        }
    }, [liveError, chatActions, activePatientId, uiDispatch]);

    useEffect(() => {
        if (chatMode !== ChatModeEnum.Live && isLive) stopSession();
    }, [chatMode, isLive, stopSession]);

    useEffect(() => {
        if (isLive && chatMode !== ChatModeEnum.Live) uiDispatch({ type: 'SET_CHAT_MODE', payload: ChatModeEnum.Live });
    }, [isLive, chatMode, uiDispatch]);

    // --- Chat Orchestrator ---
    const { handleSend, handleStop, handleClearChat, handleExportChat } = useChatOrchestrator({
        messages: activeMessages, 
        activePatientId: activePatientId,
        activePatient: activePatient, 
        chatMode: chatMode,
        uiDispatch: uiDispatch, 
        uploadedFile,
        setUploadedFile,
        isLive,
        stopSession,
        userLocation,
        clearFile
    });

    const handleViewImage = useCallback((src: string, alt: string) => {
        setViewingImage({ src, alt });
    }, []);

    const toggleLiveSession = useCallback(() => isLive ? stopSession() : startSession(activeMessages), [isLive, stopSession, startSession, activeMessages]);

    // --- LOCK SCREEN UI (Full Security) ---
    if (isLocked) {
        return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-950 text-white relative overflow-hidden">
                <div className="absolute inset-0 bg-grid-pattern opacity-10"></div>
                <div className="z-10 bg-slate-900 border border-slate-700 p-8 rounded-md shadow-2xl max-w-sm w-full text-center technical-border">
                    <ShieldCheckIcon className="w-12 h-12 text-blue-500 mx-auto mb-4 animate-pulse" />
                    <h2 className="text-xl font-display font-bold uppercase tracking-widest mb-2">Session Locked</h2>
                    <p className="text-sm text-slate-400 font-mono mb-6">Security Timeout (15m)</p>
                    <button 
                        onClick={() => {
                            lastActivityRef.current = Date.now();
                            setIsLocked(false);
                            setIsBlurred(false);
                        }}
                        className="w-full py-3 bg-blue-600 hover:bg-blue-500 text-white font-bold uppercase tracking-widest rounded-sm transition-colors"
                    >
                        Resume Session
                    </button>
                </div>
            </div>
        );
    }

    if (!process.env.API_KEY) {
         return (
            <div className="flex flex-col items-center justify-center h-screen bg-slate-100 dark:bg-slate-900 text-slate-800 dark:text-slate-200 p-4">
                <div className="bg-white dark:bg-slate-800 p-8 rounded-xl shadow-lg max-w-md text-center">
                    <div className="text-red-500 text-5xl mb-4">⚠️</div>
                    <h1 className="text-xl font-bold mb-2">API Key Missing</h1>
                    <p className="text-slate-600 dark:text-slate-400">Environment variable <code>API_KEY</code> is required.</p>
                </div>
            </div>
         );
    }

    return (
        <div 
            className="flex h-[100dvh] font-sans overflow-hidden relative text-slate-900 dark:text-slate-100"
            {...dragHandlers}
        >
            <BioMetricBackground />

            {/* CONTENT WRAPPER: Applied Blur Filter here */}
            <div className={`flex flex-1 w-full h-full relative transition-all duration-700 ${isBlurred ? 'blur-md opacity-60 grayscale scale-[0.99] pointer-events-none' : ''}`}>
                <SidebarRoster 
                    isOpen={isSidebarOpen} 
                    toggle={() => setIsSidebarOpen(!isSidebarOpen)} 
                />

                <div className="flex-1 flex flex-col min-w-0 relative z-10">
                    <Header
                        currentMode={chatMode}
                        onModeChange={(mode) => uiDispatch({ type: 'SET_CHAT_MODE', payload: mode })}
                        onClearChat={handleClearChat}
                        onExportChat={handleExportChat}
                        onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
                    />

                    {activePatient && (
                        <HeadsUpDisplay patient={activePatient} />
                    )}

                    <CDSSContainer />

                    {chatMode === ChatModeEnum.Scribe ? (
                        <ScribeInterface />
                    ) : (
                        <>
                            <MessageList 
                                messages={activeMessages} 
                                isLoading={isLoading} 
                                isLive={isLive} 
                                liveTranscript={transcript} 
                                onViewImage={handleViewImage}
                            />

                            <InputBar
                                onSend={handleSend}
                                onClearFile={clearFile}
                                setUploadedFile={setUploadedFile}
                                uploadedFile={uploadedFile}
                                isLoading={isLoading}
                                currentMode={chatMode}
                                toggleLiveSession={toggleLiveSession}
                                isLiveSessionActive={isLive}
                                onStop={handleStop}
                            />
                        </>
                    )}
                </div>
            </div>

            {/* PRIVACY SHIELD OVERLAY (Visible only when blurred) */}
            <div className={`absolute inset-0 z-[60] flex items-center justify-center pointer-events-none transition-opacity duration-500 ${isBlurred ? 'opacity-100' : 'opacity-0'}`}>
                 <div className="bg-slate-900/90 text-white px-8 py-4 rounded-full font-mono text-sm uppercase tracking-widest shadow-2xl border border-white/10 flex items-center gap-3 animate-slide-up">
                    <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse"></div>
                    <EyeIcon className="w-4 h-4 text-emerald-500" />
                    <span>Privacy Shield Active</span>
                 </div>
            </div>

            {isDragging && (
                <div className="absolute inset-0 z-50 bg-slate-900/90 backdrop-blur-sm flex items-center justify-center m-4 rounded-xl animate-fade-in pointer-events-none border-2 border-blue-500/50 shadow-[0_0_50px_rgba(59,130,246,0.3)]">
                    <div className="flex flex-col items-center text-blue-400 animate-pulse">
                        <DocumentTextIcon className="w-20 h-20 mb-6" />
                        <h2 className="text-3xl font-display font-bold tracking-tight">DATA INGESTION PROTOCOL</h2>
                        <p className="font-mono text-sm mt-2 opacity-70 uppercase tracking-widest">Release to initialize scan</p>
                    </div>
                </div>
            )}

            {viewingImage && (
                <ImageViewer 
                    src={viewingImage.src} 
                    alt={viewingImage.alt} 
                    onClose={() => setViewingImage(null)} 
                />
            )}
        </div>
    );
};

