import { FHIRObservation } from '../fhir/types';
import { HOSPITAL_PROTOCOLS } from './protocolLibrary';

/**
 * RAG RETRIEVER
 * Analyzes the incoming patient data and retrieves relevant protocol text chunks.
 * This ensures the LLM context contains the "Ground Truth" needed for evaluation.
 */
export const retrieveRelevantProtocols = (observations: FHIRObservation[]): string => {
    if (!observations || observations.length === 0) return "";

    // 1. Create a "Search Vector" from the observation codes
    // In a real app, this would be embeddings. Here, we use token matching.
    const searchTokens = observations.map(o => {
        const text = o.code.text?.toLowerCase() || '';
        const coding = o.code.coding?.[0]?.display?.toLowerCase() || '';
        return `${text} ${coding}`;
    }).join(' ');

    // 2. Filter Protocols based on relevance
    // If a protocol's keywords appear in the patient data, we include it.
    const relevantProtocols = HOSPITAL_PROTOCOLS.filter(protocol => {
        return protocol.keywords.some(keyword => searchTokens.includes(keyword));
    });

    if (relevantProtocols.length === 0) return "";

    // 3. Construct the Context Block
    const contextBlock = relevantProtocols.map(p => `
    >>> BEGIN OFFICIAL PROTOCOL: ${p.title} (ID: ${p.id})
    ${p.content}
    <<< END OFFICIAL PROTOCOL
    `).join('\n\n');

    return `
    *** RETRIEVED HOSPITAL PROTOCOLS (GROUND TRUTH) ***
    The following are the active clinical protocols relevant to this patient.
    Use ONLY these definitions to determine safety alerts.

    ${contextBlock}
    `;
};

import { GoogleGenAI } from "@google/genai";
import { v4 as uuidv4 } from 'uuid';
import { FHIRObservation } from '../fhir/types';
import { CDSSAlert } from './types';
import { CDSS_CHECK_PROMPT } from '../../constants';
import { cleanJsonOutput } from '../../utils';
import { retrieveRelevantProtocols } from './retrievalService';

export const evaluateClinicalSafety = async (observations: FHIRObservation[]): Promise<CDSSAlert[]> => {
    if (!observations || observations.length === 0) return [];

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // 1. Format observations for the model
        const obsString = observations.map(o => 
            `- ${o.code.text || 'Unknown Test'}: ${o.valueQuantity?.value ?? 'N/A'} ${o.valueQuantity?.unit || ''} (Time: ${o.effectiveDateTime || 'Unknown'})`
        ).join('\n');

        // 2. RAG STEP: Retrieve relevant protocols based on the data
        const protocolContext = retrieveRelevantProtocols(observations);

        // 3. Construct Prompt
        const contents = [
            {
                role: 'user',
                parts: [
                    { text: CDSS_CHECK_PROMPT },
                    { text: protocolContext }, // INJECTED KNOWLEDGE
                    { text: `\n\n*** PATIENT OBSERVATIONS TO EVALUATE ***\n${obsString}` }
                ]
            }
        ];

        // 4. Generate with Low Temperature for adherence to protocol
        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: contents,
            config: {
                responseMimeType: 'application/json',
                temperature: 0.1 // Strict adherence
            }
        });

        const text = response.text;
        if (!text) return [];

        const cleaned = cleanJsonOutput(text);
        const parsed = JSON.parse(cleaned);

        if (parsed.alerts && Array.isArray(parsed.alerts)) {
            return parsed.alerts.map((alert: any) => ({
                id: uuidv4(),
                ruleId: alert.source_citation ? `prot-${alert.source_citation}` : `ai-${Date.now()}`, // Use protocol ID as key if avail
                title: alert.title || 'CLINICAL ALERT',
                description: alert.description || 'Potential protocol violation detected.',
                level: (alert.level === 'Critical' || alert.level === 'Warning') ? alert.level : 'Info',
                timestamp: Date.now(),
                triggers: Array.isArray(alert.triggers) ? alert.triggers : [],
                actions: Array.isArray(alert.actions) ? alert.actions : [{ label: 'Dismiss', type: 'dismiss' }]
            }));
        }

        return [];

    } catch (e) {
        console.warn("CDSS AI Check Failed:", e);
        return [];
    }
};

